//! The golden fixtures generated by packages/protocol (TypeScript): every valid
//! case decodes to the listed fields and re-encodes byte-exactly; every
//! invalid case is refused.

use serde_json::Value;
use tmuxedo_protocol::{DataFrame, DataKind};

fn fixtures() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../../packages/protocol/fixtures/data-frames.json"
    );
    let text = std::fs::read_to_string(path).unwrap_or_else(|e| panic!("read {path}: {e}"));
    serde_json::from_str(&text).expect("fixtures are JSON")
}

#[test]
fn valid_fixtures_decode_and_reencode_exactly() {
    let f = fixtures();
    let valid = f["valid"].as_array().expect("valid[]");
    assert!(!valid.is_empty());
    for case in valid {
        let name = case["name"].as_str().unwrap();
        let bytes = hex::decode(case["hex"].as_str().unwrap()).unwrap();
        let frame = DataFrame::decode(&bytes).unwrap_or_else(|| panic!("{name}: refused"));
        assert_eq!(
            frame.kind,
            DataKind::from_u8(case["kind"].as_u64().unwrap() as u8).unwrap(),
            "{name} kind"
        );
        assert_eq!(frame.gap, case["gap"].as_bool().unwrap(), "{name} gap");
        assert_eq!(frame.req as u64, case["req"].as_u64().unwrap(), "{name} req");
        assert_eq!(frame.pane_id, case["paneId"].as_str().unwrap(), "{name} paneId");
        let offset: u64 = case["offset"].as_str().unwrap().parse().unwrap();
        assert_eq!(frame.offset, offset, "{name} offset");
        assert_eq!(
            frame.payload,
            hex::decode(case["payloadHex"].as_str().unwrap()).unwrap(),
            "{name} payload"
        );
        assert_eq!(frame.encode().unwrap(), bytes, "{name} re-encode");
    }
}

#[test]
fn invalid_fixtures_are_refused() {
    let f = fixtures();
    let invalid = f["invalid"].as_array().expect("invalid[]");
    assert!(!invalid.is_empty());
    for case in invalid {
        let name = case["name"].as_str().unwrap();
        let bytes = hex::decode(case["hex"].as_str().unwrap()).unwrap();
        assert!(DataFrame::decode(&bytes).is_none(), "{name} was accepted");
    }
}

/// `login_callback` (gateway → runner) from packages/protocol/fixtures/login-callback.json.
#[test]
fn login_callback_frames_parse() {
    use tmuxedo_protocol::frames::{parse_gateway, GatewayFrame, Parsed};
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../../packages/protocol/fixtures/login-callback.json"
    );
    let f: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let cases = f["runnerFrames"].as_array().expect("runnerFrames[]");
    assert!(!cases.is_empty());
    for c in cases {
        let want = &c["frame"];
        match parse_gateway(c["text"].as_str().unwrap()) {
            Parsed::Frame(GatewayFrame::LoginCallback { id, pane_id, url }) => {
                assert_eq!(id, want["id"].as_str().unwrap(), "{}", c["name"]);
                assert_eq!(pane_id, want["paneId"].as_str().unwrap(), "{}", c["name"]);
                assert_eq!(url, want["url"].as_str().unwrap(), "{}", c["name"]);
            }
            other => panic!("{}: {other:?}", c["name"]),
        }
    }
    // Junk is refused, never panics.
    for bad in [
        r#"{"t":"login_callback","paneId":"w1:p1","url":"http://x"}"#,
        r#"{"t":"login_callback","id":"","paneId":"w1:p1","url":"http://x"}"#,
        r#"{"t":"login_callback","id":"a","paneId":"w1:p1","url":""}"#,
        r#"{"t":"login_callback","id":"a","paneId":"w1:p1","url":5}"#,
    ] {
        assert!(matches!(parse_gateway(bad), Parsed::Invalid(_)), "{bad}");
    }
}

/// Agent status frames (runner → gateway) from packages/protocol/fixtures/agent-status.json:
/// every status from every source parses, and the runner writes exactly what the
/// TypeScript side reads.
#[test]
fn agent_status_frames_round_trip() {
    use tmuxedo_protocol::frames::{AgentSource, AgentStatus, RunnerFrame};
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../../packages/protocol/fixtures/agent-status.json"
    );
    let f: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let frames = f["frames"].as_array().expect("frames[]");
    let mut seen = std::collections::BTreeSet::new();
    let mut none = false;
    for c in frames {
        let name = c["name"].as_str().unwrap();
        let frame: RunnerFrame =
            serde_json::from_str(c["text"].as_str().unwrap()).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(serde_json::to_value(&frame).unwrap(), c["frame"], "{name}");
        let RunnerFrame::Status { agent, .. } = frame else {
            panic!("{name}: not a status frame")
        };
        match agent {
            Some(a) => {
                seen.insert(format!("{:?}/{:?}", a.status, a.source));
            }
            None => none = true,
        }
    }
    assert!(none, "a frame without an agent");
    for status in [
        AgentStatus::Working,
        AgentStatus::Blocked,
        AgentStatus::Done,
        AgentStatus::Idle,
        AgentStatus::Unknown,
    ] {
        for source in [AgentSource::Reported, AgentSource::Screen, AgentSource::Heuristic] {
            assert!(
                seen.contains(&format!("{status:?}/{source:?}")),
                "{status:?} from {source:?} missing"
            );
        }
    }
    for c in f["invalid"].as_array().expect("invalid[]") {
        assert!(
            serde_json::from_str::<RunnerFrame>(c["text"].as_str().unwrap()).is_err(),
            "{} was accepted",
            c["name"]
        );
    }
}

/// The runner-proof input (docs/protocol.md "Runner proof") from packages/protocol/fixtures/runner-proof.json.
#[test]
fn runner_proof_input_matches_the_fixture() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../../packages/protocol/fixtures/runner-proof.json"
    );
    let f: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let got = tmuxedo_protocol::runner_proof_input(f["nonce"].as_str().unwrap(), f["lookup"].as_str().unwrap());
    assert_eq!(got, f["input"].as_str().unwrap());
    assert_eq!(f["frames"]["challenge"]["t"], "challenge");
    assert_eq!(f["frames"]["proof"]["t"], "proof");
}

/// Names (packages/protocol/fixtures/names.json, also checked by names.test.ts).
fn names_fixtures() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../../packages/protocol/fixtures/names.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).unwrap_or_else(|e| panic!("read {path}: {e}"))).unwrap()
}

#[test]
fn names_clean_like_the_typescript_side() {
    use tmuxedo_protocol::names::{clean_name, NAME_MAX};
    let f = names_fixtures();
    assert_eq!(f["max"].as_u64().unwrap() as usize, NAME_MAX);
    let cases = f["clean"].as_array().expect("clean[]");
    assert!(cases.len() >= 20);
    for c in cases {
        let (input, want) = (c["in"].as_str().unwrap(), c["out"].as_str().unwrap());
        assert_eq!(clean_name(input), want, "{}", c["name"]);
        assert_eq!(clean_name(want), want, "{} is idempotent", c["name"]);
    }
}

#[test]
fn names_defaults_like_the_typescript_side() {
    use tmuxedo_protocol::names::{default_tab_name, default_workspace_name};
    for c in names_fixtures()["defaults"].as_array().expect("defaults[]") {
        let id = c["id"].as_str().unwrap();
        match c["kind"].as_str().unwrap() {
            "workspace" => assert_eq!(default_workspace_name(id), c["name"].as_str().unwrap()),
            "tab" => assert_eq!(default_tab_name(id), c["name"].as_str().unwrap()),
            _ => assert!(c["name"].is_null(), "a pane has no default name"),
        }
    }
}

// ── agent chat (packages/protocol/fixtures/chat.json) ─────────────────────

fn chat_fixtures() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../../packages/protocol/fixtures/chat.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

/// Every event type, as the TypeScript side wrote it, parses and serialises
/// back to the same JSON: the two models cannot drift.
#[test]
fn chat_events_round_trip_exactly() {
    use tmuxedo_protocol::chat::{parse_event, EVENT_TYPES};
    let f = chat_fixtures();
    let events = f["events"].as_array().unwrap();
    let mut seen = std::collections::BTreeSet::new();
    for e in events {
        let text = e.to_string();
        let ev = parse_event(&text).unwrap_or_else(|| panic!("refused: {text}"));
        seen.insert(ev.body.kind());
        assert_eq!(&serde_json::to_value(&ev).unwrap(), e, "round trip of {text}");
    }
    assert_eq!(seen.len(), EVENT_TYPES.len(), "one of every type");
    for c in f["invalidEvents"].as_array().unwrap() {
        assert!(
            parse_event(c["text"].as_str().unwrap()).is_none(),
            "{} was accepted",
            c["name"]
        );
    }
}

/// The optional tool and thought fields (docs/design/chat-tools.md §14): a
/// value of the wrong type is refused here as it is in TypeScript, a value
/// from a later version is read past, and the fixture shows every field
/// both present and absent.
#[test]
fn chat_optional_fields_are_checked_and_never_required() {
    use tmuxedo_protocol::chat::{
        parse_event, ChatBody, MAX_TOOL_ATTACHMENTS, MAX_TOOL_NAME, MAX_TOOL_OUTPUT, MAX_TOOL_SUBJECT, OUTPUT_KEPT,
        TOOL_STATUSES, TOOL_VARIANTS,
    };
    let f = chat_fixtures();
    for c in f["invalidOptional"].as_array().unwrap() {
        assert!(
            parse_event(c["text"].as_str().unwrap()).is_none(),
            "{} was accepted",
            c["name"]
        );
    }
    for c in f["tolerated"].as_array().unwrap() {
        assert!(
            parse_event(c["text"].as_str().unwrap()).is_some(),
            "{} was refused",
            c["name"]
        );
    }
    let events: Vec<_> = f["events"]
        .as_array()
        .unwrap()
        .iter()
        .map(|e| parse_event(&e.to_string()).unwrap().body)
        .collect();
    let mut statuses = std::collections::BTreeSet::new();
    let mut kept = std::collections::BTreeSet::new();
    // (with every optional field absent, with some present) per event type.
    let (mut thought, mut started, mut done) = ((false, false), (false, false), (false, false));
    let mut lines = vec![];
    for b in &events {
        match b {
            ChatBody::ThoughtDone {
                duration_ms, redacted, ..
            } => {
                if duration_ms.is_none() && !redacted {
                    thought.0 = true;
                } else {
                    thought.1 = true;
                }
            }
            ChatBody::ToolStarted {
                name,
                server,
                subject,
                variant,
                ..
            } => {
                if name.is_none() && server.is_none() && subject.is_none() && variant.is_none() {
                    started.0 = true;
                } else {
                    started.1 = true;
                }
                if let Some(v) = variant {
                    assert!(TOOL_VARIANTS.contains(&v.as_str()), "{v}");
                }
            }
            ChatBody::ToolUpdated { diff: Some(d), .. } => lines.push(d.line),
            ChatBody::ToolDone {
                status,
                exit_code,
                duration_ms,
                output_bytes,
                output_kept,
                attachments,
                result_count,
                ..
            } => {
                statuses.insert(status.as_str());
                if let Some(k) = output_kept {
                    kept.insert(k.as_str());
                }
                if exit_code.is_none()
                    && duration_ms.is_none()
                    && output_bytes.is_none()
                    && output_kept.is_none()
                    && attachments.is_empty()
                    && result_count.is_none()
                {
                    done.0 = true;
                } else {
                    done.1 = true;
                }
            }
            _ => {}
        }
    }
    assert_eq!((thought, started, done), ((true, true), (true, true), (true, true)));
    assert!(lines.contains(&None) && lines.contains(&Some(40)), "{lines:?}");
    assert_eq!(statuses.into_iter().collect::<Vec<_>>(), {
        let mut s = TOOL_STATUSES.to_vec();
        s.sort();
        s
    });
    assert_eq!(kept.into_iter().collect::<Vec<_>>(), OUTPUT_KEPT);
    assert_eq!(
        (MAX_TOOL_OUTPUT, MAX_TOOL_NAME, MAX_TOOL_SUBJECT, MAX_TOOL_ATTACHMENTS),
        (16384, 64, 300, 20),
        "the limits TypeScript states"
    );
    // An event written before the fields existed reads as it always did, and is written back without them.
    let old = r#"{"seq":7,"at":"t","sessionId":"c-fixture0001","type":"tool.done","toolId":"toolu_1","status":"failed","summary":"1 test failed"}"#;
    let ev = parse_event(old).unwrap();
    assert_eq!(
        serde_json::to_value(&ev).unwrap(),
        serde_json::from_str::<Value>(old).unwrap()
    );
}

#[test]
fn chat_frames_decode_and_reencode_exactly() {
    use tmuxedo_protocol::ChatFrame;
    let f = chat_fixtures();
    for c in f["frames"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let bytes = hex::decode(c["hex"].as_str().unwrap()).unwrap();
        let fr = ChatFrame::decode(&bytes).unwrap_or_else(|| panic!("{name}: refused"));
        assert_eq!(fr.session_id, c["sessionId"].as_str().unwrap(), "{name}");
        assert_eq!(fr.seq.to_string(), c["seq"].as_str().unwrap(), "{name}");
        assert_eq!(fr.req as u64, c["req"].as_u64().unwrap(), "{name}");
        assert_eq!(fr.gap, c["gap"].as_bool().unwrap(), "{name}");
        assert_eq!(fr.ephemeral, c["ephemeral"].as_bool().unwrap(), "{name}");
        assert_eq!(
            fr.payload,
            hex::decode(c["payloadHex"].as_str().unwrap()).unwrap(),
            "{name}"
        );
        assert_eq!(fr.encode().unwrap(), bytes, "{name} re-encode");
        assert!(
            DataFrame::decode(&bytes).is_none(),
            "{name}: a chat frame is not a pane frame"
        );
    }
    for c in f["invalidFrames"].as_array().unwrap() {
        let bytes = hex::decode(c["hex"].as_str().unwrap()).unwrap();
        assert!(ChatFrame::decode(&bytes).is_none(), "{} was accepted", c["name"]);
    }
}

#[test]
fn chat_control_frames() {
    use tmuxedo_protocol::frames::{parse_gateway, GatewayFrame, Parsed, RunnerFrame};
    let f = chat_fixtures();
    for c in f["gatewayFrames"].as_array().unwrap() {
        let want = &c["frame"];
        match parse_gateway(c["text"].as_str().unwrap()) {
            Parsed::Frame(GatewayFrame::ChatAttach { req, session_id, from }) => {
                assert_eq!(req as u64, want["req"].as_u64().unwrap());
                assert_eq!(session_id, want["sessionId"].as_str().unwrap());
                assert_eq!(from, want["from"].as_u64());
            }
            Parsed::Frame(GatewayFrame::ChatDetach { session_id }) => {
                assert_eq!(session_id, want["sessionId"].as_str().unwrap());
            }
            other => panic!("{}: {other:?}", c["name"]),
        }
    }
    for t in f["invalidGatewayFrames"].as_array().unwrap() {
        assert!(
            matches!(parse_gateway(t.as_str().unwrap()), Parsed::Invalid(_)),
            "{t} accepted"
        );
    }
    // What the runner sends is what TypeScript parses.
    for c in f["runnerFrames"].as_array().unwrap() {
        let want: Value = serde_json::from_str(c["text"].as_str().unwrap()).unwrap();
        let f = RunnerFrame::ChatAttached {
            req: want["req"].as_u64().unwrap() as u32,
            session_id: want["sessionId"].as_str().unwrap().into(),
            ok: want["ok"].as_bool().unwrap(),
            last_seq: want["lastSeq"].as_u64().unwrap(),
            code: want["code"].as_str().map(str::to_owned),
        };
        assert_eq!(
            serde_json::from_str::<Value>(&f.to_json()).unwrap(),
            want,
            "{}",
            c["name"]
        );
    }
}

// ── machine stats (packages/protocol/fixtures/stats.json) ─────────────────

fn stats_fixtures() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../../packages/protocol/fixtures/stats.json"
    );
    let text = std::fs::read_to_string(path).unwrap_or_else(|e| panic!("read {path}: {e}"));
    serde_json::from_str(&text).expect("fixtures are JSON")
}

#[test]
fn stats_samples_decode_and_reencode_exactly() {
    use tmuxedo_protocol::frames::RunnerFrame;
    use tmuxedo_protocol::stats::{FEATURE_STATS, STATS_HZ_MAX, STATS_HZ_MIN};
    let f = stats_fixtures();
    assert_eq!(f["feature"], FEATURE_STATS);
    assert_eq!(f["hz"]["min"].as_f64(), Some(STATS_HZ_MIN));
    assert_eq!(f["hz"]["max"].as_f64(), Some(STATS_HZ_MAX));
    let samples = f["samples"].as_array().expect("samples[]");
    assert!(!samples.is_empty());
    for case in samples {
        let name = case["name"].as_str().unwrap();
        let frame: RunnerFrame =
            serde_json::from_value(case["frame"].clone()).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert!(matches!(frame, RunnerFrame::Stats(_)), "{name}");
        assert_eq!(serde_json::to_value(&frame).unwrap(), case["frame"], "{name} re-encode");
    }
}

#[test]
fn stats_gateway_frames_parse_to_a_rate_or_stop() {
    use tmuxedo_protocol::frames::{parse_gateway, GatewayFrame, Parsed};
    let f = stats_fixtures();
    for case in f["gateway"].as_array().expect("gateway[]") {
        let name = case["name"].as_str().unwrap();
        assert_eq!(
            parse_gateway(case["text"].as_str().unwrap()),
            Parsed::Frame(GatewayFrame::Stats {
                hz: case["hz"].as_f64().unwrap()
            }),
            "{name}"
        );
    }
    for case in f["gatewayInvalid"].as_array().expect("gatewayInvalid[]") {
        let name = case["name"].as_str().unwrap();
        assert!(
            matches!(parse_gateway(case["text"].as_str().unwrap()), Parsed::Invalid(_)),
            "{name} was accepted"
        );
    }
}

// ── AI usage (packages/protocol/fixtures/usage.json) ──────────────────────

#[test]
fn usage_records_decode_reencode_and_refuse_the_same_as_the_other_codec() {
    use tmuxedo_protocol::frames::RunnerFrame;
    use tmuxedo_protocol::usage::{UsageRecord, FEATURE_USAGE, USAGE_MIN_INTERVAL_MS, USAGE_WINDOWS_MAX};
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../../packages/protocol/fixtures/usage.json"
    );
    let text = std::fs::read_to_string(path).unwrap_or_else(|e| panic!("read {path}: {e}"));
    let f: Value = serde_json::from_str(&text).expect("fixtures are JSON");
    assert_eq!(f["feature"], FEATURE_USAGE);
    assert_eq!(f["minIntervalMs"].as_u64(), Some(USAGE_MIN_INTERVAL_MS));
    assert_eq!(f["windowsMax"].as_u64(), Some(USAGE_WINDOWS_MAX as u64));
    let decode = |case: &Value| -> Option<UsageRecord> {
        match serde_json::from_value::<RunnerFrame>(case["frame"].clone()).ok()? {
            RunnerFrame::Usage(u) => Some(u),
            _ => None,
        }
    };
    for case in f["records"].as_array().expect("records[]") {
        let name = case["name"].as_str().unwrap();
        let u = decode(case).unwrap_or_else(|| panic!("{name}: not a usage frame"));
        assert!(u.ok(), "{name}");
        assert_eq!(
            serde_json::to_value(RunnerFrame::Usage(u)).unwrap(),
            case["frame"],
            "{name} re-encode"
        );
    }
    for case in f["invalid"].as_array().expect("invalid[]") {
        let name = case["name"].as_str().unwrap();
        assert!(!decode(case).is_some_and(|u| u.ok()), "{name}");
    }
    let s = &f["stripped"];
    let u = decode(s).expect("stripped decodes");
    assert!(u.ok());
    assert_eq!(serde_json::to_value(&u).unwrap(), s["clean"]);
}
